6	static void expect_extrude(Halfedge_Mesh &mesh, Halfedge_Mesh::FaceRef face, Vec3 move, float shrink, Halfedge_Mesh const &after) {
7		size_t numVerts = mesh.vertices.size();
8		size_t numEdges = mesh.edges.size();
9		size_t numFaces = mesh.faces.size();
10	
11		std::set<Vec3> old_verts;
12		{
13			Halfedge_Mesh::HalfedgeCRef h = face->halfedge;
14			do {
15				old_verts.insert(h->vertex->position);
16				h = h->next;
17			} while (h != face->halfedge);
18		}
19	
20	
21		std::set<Halfedge_Mesh::FaceCRef> old_faces;
22		for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
23			old_faces.insert(f);
24		}
25	
26		if (auto ret = mesh.extrude_face(face)) {
27			if (auto msg = mesh.validate()) {
28				throw Test::error("Invalid mesh: " + msg.value().second);
29			}
30	
31			// check if returned face is the same face
32			if (ret != face) {
33				throw Test::error("Did not return the same face!");
34			}
35			// check if returned face is the same as input face
36			if (face->id != ret.value()->id) {
37				throw Test::error("Bevel face did not return the input face!");
38			}
39	
40			// check if new side faces are quads
41			std::set<Halfedge_Mesh::FaceCRef> new_faces;
42			for (Halfedge_Mesh::FaceRef f = mesh.faces.begin(); f != mesh.faces.end(); f++) {
43				new_faces.insert(f);
44			}
45			std::set<Halfedge_Mesh::FaceCRef> diff;
46			std::set_difference(new_faces.begin(), new_faces.end(), old_faces.begin(), old_faces.end(),
47			                    std::inserter(diff, diff.end()));
48			for (Halfedge_Mesh::FaceCRef face_diff : diff) {
49				// assume the access is safe because ids are created from the new mesh directly
50				if (face_diff->degree() != 4) {
51					throw Test::error("Bevel face created incorrect side faces!");
52				}
53			}
54	
55			// check the number of new elements created
56			size_t faceDeg = ret.value()->degree();
57			if (numVerts + faceDeg != mesh.vertices.size()) {
58				throw Test::error("Bevel face created incorrect number of vertices!");
59			}
60			if (numEdges + faceDeg * 2 != mesh.edges.size()) {
61				throw Test::error("Bevel face created incorrect number of edges!");
62			}
63			if (numFaces + faceDeg != mesh.faces.size()) {
64				throw Test::error("Bevel face created incorrect number of faces!");
65			}
66	
67			// extract the newly created vertices, check their positions are identical to input vertices
68			std::set<Vec3> new_verts;
69			Halfedge_Mesh::VertexRef v = --mesh.vertices.end();
70			for (size_t i = 0; i < old_verts.size(); i++) {
71				new_verts.insert(v->position);
72				v--;
73			}
74			if (old_verts != new_verts) {
75				throw Test::error("Bevel face created vertices at incorrect positions!");
76			}
77	
78			mesh.extrude_positions(face, move, shrink);
79			// check mesh shape:
80			if (auto difference = Test::differs(mesh, after, Test::CheckAllBits)) {
81				throw Test::error("Resulting mesh did not match expected: " + *difference);
82			}
83		} else {
84			throw Test::error("extrude_face rejected operation!");
85		}
86	}
