160	Transform Widgets::apply_action(const Transform& pose) {
161	
162		Transform result = pose;
163		Vec3 vaxis;
164	
165		const uint8_t axis_u = static_cast<uint8_t>(axis);
166		vaxis[axis_u] = 1.0f;
167	
168		switch (active) {
169		case Widget_Type::move: {
170			result.translation = pose.translation + drag_end - drag_start;
171		} break;
172		case Widget_Type::rotate: {
173			Quat _rot_ = Quat::axis_angle(vaxis, drag_end[axis_u]);
174			result.rotation = _rot_ * pose.rotation;
175		} break;
176		case Widget_Type::scale: {
177			if (univ_scl) {
178				result.scale = drag_end * pose.scale;
179			} else {
180				result.scale = Vec3{1.0f};
181				result.scale[axis_u] = drag_end[axis_u];
182				Mat4 _rot_ = pose.rotation.to_mat();
183				Mat4 trans =
184					Mat4::transpose(_rot_) * Mat4::scale(result.scale) * _rot_ * Mat4::scale(pose.scale);
185				result.scale = Vec3(trans[0][0], trans[1][1], trans[2][2]);
186			}
187		} break;
188		case Widget_Type::extrude:
189		case Widget_Type::inset:
190		case Widget_Type::bevel: {
191			Vec2 off = bevel_start - bevel_end;
192			result.translation = 2.0f * Vec3(off.x, -off.y, 0.0f);
193		} break;
194		default: assert(false);
195		}
196	
197		return result;
198	}
