200	bool Widgets::to_axis(Vec3 obj_pos, Vec3 cam_pos, Vec3 dir, Vec3& hit) {
201	
202		const uint8_t axis_u = static_cast<uint8_t>(axis);
203	
204		Vec3 axis1;
205		axis1[axis_u] = 1.0f;
206		Vec3 axis2;
207		axis2[(axis_u + 1) % 3] = 1.0f;
208		Vec3 axis3;
209		axis3[(axis_u + 2) % 3] = 1.0f;
210	
211		Line select(cam_pos, dir);
212		Line target(obj_pos, axis1);
213		Plane l(obj_pos, axis2);
214		Plane r(obj_pos, axis3);
215	
216		Vec3 hit1, hit2;
217		bool hl = l.hit(select, hit1);
218		bool hr = r.hit(select, hit2);
219		if (!hl && !hr)
220			return false;
221		else if (!hl)
222			hit = hit2;
223		else if (!hr)
224			hit = hit1;
225		else
226			hit = (hit1 - cam_pos).norm() > (hit2 - cam_pos).norm() ? hit2 : hit1;
227	
228		hit = target.closest(hit);
229		return hit.valid();
230	}
