232	bool Widgets::to_axis3(Vec3 obj_pos, Vec3 cam_pos, Vec3 dir, Vec3& hit) {
233	
234		Vec3 axis1{1.0f, 0.0f, 0.0f};
235		Vec3 axis2{0.0f, 1.0f, 0.0f};
236		Vec3 axis3{0.0f, 0.0f, 1.0f};
237	
238		Line select(cam_pos, dir);
239		Line target(obj_pos, axis1);
240	
241		Plane k(obj_pos, axis1);
242		Plane l(obj_pos, axis2);
243		Plane r(obj_pos, axis3);
244	
245		Vec3 hit1, hit2, hit3;
246		bool hk = k.hit(select, hit1);
247		bool hl = l.hit(select, hit2);
248		bool hr = r.hit(select, hit3);
249	
250		if (!hl && !hr && !hk) return false;
251	
252		Vec3 close{FLT_MAX};
253		if (hk && (hit1 - cam_pos).norm() < (close - cam_pos).norm()) close = hit1;
254		if (hl && (hit2 - cam_pos).norm() < (close - cam_pos).norm()) close = hit2;
255		if (hr && (hit3 - cam_pos).norm() < (close - cam_pos).norm()) close = hit3;
256	
257		hit = close;
258		return hit.valid();
259	}
