294	
295		} else {
296	
297			bool good;
298	
299			if (drag_plane)
300				good = to_plane(pos, cam, dir, norm, hit);
301			else if (univ_scl)
302				good = to_axis3(pos, cam, dir, hit);
303			else
304				good = to_axis(pos, cam, dir, hit);
305	
306			if (!good) return;
307	
308			if (active == Widget_Type::bevel || active == Widget_Type::inset ||
309			    active == Widget_Type::extrude) {
310				bevel_start = bevel_end = spos;
311			} else if (active == Widget_Type::move) {
312				drag_start = drag_end = hit;
313			} else {
314				drag_start = hit;
315				drag_end = Vec3{1.0f};
316			}
317	
318			if (active != Widget_Type::bevel && active != Widget_Type::extrude &&
319			    active != Widget_Type::inset)
320				generate_lines(pos);
321		}
322	}
